/**
 * @deprecated Use `src/types/project.ts` once type definitions are centralized
 */
export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[]; // Array of user IDs
}

/**
 * Manages projects and their membership.
 * Adheres to ADR-002: Service-Owned Data Stores.
 */
export class ProjectService {
    private projectStore: Map<string, Project>;

    constructor() {
        this.projectStore = new Map();
    }

    /**
     * Creates a new project.
     * @param name The name of the project.
     * @param description The description of the project.
     * @param initialMemberId Optional ID of a user to add as an initial member.
     * @returns The newly created project.
     */
    create(name: string, description: string, initialMemberId?: string): Project {
        const newProject: Project = {
            id: randomUUID(),
            name,
            description,
            memberIds: initialMemberId ? [initialMemberId] : [],
        };
        this.projectStore.set(newProject.id, newProject);
        return newProject;
    }

    /**
     * Retrieves a project by its ID.
     * @param id The ID of the project.
     * @returns The project, or undefined if not found.
     */
    getById(id: string): Project | undefined {
        return this.projectStore.get(id);
    }

    /**
     * Retrieves all projects.
     * @returns An array of all projects.
     */
    getAll(): Project[] {
        return Array.from(this.projectStore.values());
    }

    /**
     * Updates an existing project.
     * @param id The ID of the project to update.
     * @param updates An object containing the fields to update (name, description).
     * @returns The updated project, or undefined if not found.
     */
    update(id: string, updates: { name?: string; description?: string }): Project | undefined {
        const project = this.projectStore.get(id);
        if (!project) {
            return undefined;
        }

        if (updates.name !== undefined) {
            project.name = updates.name;
        }
        if (updates.description !== undefined) {
            project.description = updates.description;
        }

        this.projectStore.set(id, project); // Re-set to ensure map update
        return { ...project }; // Return a copy
    }

    /**
     * Deletes a project by its ID.
     * @param id The ID of the project to delete.
     * @returns True if the project was deleted, false otherwise.
     */
    delete(id: string): boolean {
        return this.projectStore.delete(id);
    }

    /**
     * Adds a member to a project.
     * @param projectId The ID of the project.
     * @param userId The ID of the user to add as a member.
     * @returns The updated project, or undefined if project not found or user already a member.
     */
    addMember(projectId: string, userId: string): Project | undefined {
        const project = this.projectStore.get(projectId);
        if (!project) {
            return undefined; // Project not found
        }

        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
            this.projectStore.set(projectId, project);
            return { ...project };
        }
        return { ...project }; // User already a member, return current project state
    }

    /**
     * Removes a member from a project.
     * @param projectId The ID of the project.
     * @param userId The ID of the user to remove from members.
     * @returns The updated project, or undefined if project not found or user not a member.
     */
    removeMember(projectId: string, userId: string): Project | undefined {
        const project = this.projectStore.get(projectId);
        if (!project) {
            return undefined; // Project not found
        }

        const initialLength = project.memberIds.length;
        project.memberIds = project.memberIds.filter(id => id !== userId);

        if (project.memberIds.length < initialLength) {
            this.projectStore.set(projectId, project);
            return { ...project };
        }
        return { ...project }; // User not a member, return current project state
    }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

/**
 * @deprecated Use `src/types/task.ts` once type definitions are centralized
 */
export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: string | null;
    projectId: string;
}

/**
 * Manages tasks with status transitions and publishes related events.
 * Adheres to ADR-002: Service-Owned Data Stores.
 */
export class TaskService {
    private taskStore: Map<string, Task>;
    private eventBus: EventBus;

    constructor(eventBus: EventBus) {
        this.taskStore = new Map();
        this.eventBus = eventBus;
    }

    /**
     * Creates a new task.
     * @param title The title of the task.
     * @param description The description of the task.
     * @param projectId The ID of the project the task belongs to.
     * @param assigneeId Optional ID of the user assigned to the task.
     * @returns The newly created task.
     */
    create(title: string, description: string, projectId: string, assigneeId: string | null = null): Task {
        const newTask: Task = {
            id: randomUUID(),
            title,
            description,
            status: "todo", // Default status
            assigneeId,
            projectId,
        };
        this.taskStore.set(newTask.id, newTask);

        if (assigneeId) {
            this.eventBus.publish("task.assigned", {
                taskId: newTask.id,
                taskTitle: newTask.title,
                assigneeId: assigneeId,
            });
        }

        return newTask;
    }

    /**
     * Retrieves a task by its ID.
     * @param id The ID of the task.
     * @returns The task, or undefined if not found.
     */
    getById(id: string): Task | undefined {
        return this.taskStore.get(id);
    }

    /**
     * Retrieves all tasks for a given project.
     * @param projectId The ID of the project.
     * @returns An array of tasks belonging to the project.
     */
    getByProject(projectId: string): Task[] {
        return Array.from(this.taskStore.values()).filter(task => task.projectId === projectId);
    }

    /**
     * Updates an existing task.
     * @param id The ID of the task to update.
     * @param updates An object containing the fields to update (title, description, assigneeId).
     * @returns The updated task, or undefined if not found.
     */
    update(id: string, updates: { title?: string; description?: string; assigneeId?: string | null }): Task | undefined {
        const task = this.taskStore.get(id);
        if (!task) {
            return undefined; // Task not found
        }

        const oldAssigneeId = task.assigneeId;

        if (updates.title !== undefined) {
            task.title = updates.title;
        }
        if (updates.description !== undefined) {
            task.description = updates.description;
        }
        if (updates.assigneeId !== undefined) {
            task.assigneeId = updates.assigneeId;
        }

        this.taskStore.set(id, task);

        if (updates.assigneeId !== undefined && oldAssigneeId !== updates.assigneeId) {
            this.eventBus.publish("task.assigned", {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
            });
        }

        return { ...task };
    }

    /**
     * Deletes a task by its ID.
     * @param id The ID of the task to delete.
     * @returns True if the task was deleted, false otherwise.
     */
    delete(id: string): boolean {
        return this.taskStore.delete(id);
    }

    /**
     * Assigns a user to a task.
     * @param id The ID of the task.
     * @param assigneeId The ID of the user to assign.
     * @returns The updated task, or undefined if not found.
     */
    assign(id: string, assigneeId: string): Task | undefined {
        const task = this.taskStore.get(id);
        if (!task) {
            return undefined;
        }

        if (task.assigneeId !== assigneeId) {
            task.assigneeId = assigneeId;
            this.taskStore.set(id, task);
            this.eventBus.publish("task.assigned", {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
            });
        }
        return { ...task };
    }

    /**
     * Changes the status of a task, enforcing forward-only transitions.
     * @param id The ID of the task.
     * @param newStatus The new status to set.
     * @returns The updated task, or undefined if not found or transition is invalid.
     */
    changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
        const task = this.taskStore.get(id);
        if (!task) {
            return undefined;
        }

        const oldStatus = task.status;

        if (!this.isValidStatusTransition(oldStatus, newStatus)) {
            console.warn(`Invalid status transition for task ${id}: ${oldStatus} -> ${newStatus}`);
            return undefined; // Invalid transition
        }

        task.status = newStatus;
        this.taskStore.set(id, task);
        this.eventBus.publish("task.statusChanged", {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
            oldStatus,
            newStatus,
        });

        return { ...task };
    }

    private isValidStatusTransition(oldStatus: TaskStatus, newStatus: TaskStatus): boolean {
        if (oldStatus === "todo") {
            return newStatus === "in-progress";
        } else if (oldStatus === "in-progress") {
            return newStatus === "done";
        } else if (oldStatus === "done") {
            return false; // Cannot transition from 'done'
        }
        return false; // Should not happen
    }
}

